      "INSERT OR IGNORE INTO _electric_trigger_settings (namespace, tablename, flag) VALUES ('main', 'accounts', 1);",
      "DROP TRIGGER IF EXISTS update_ensure_main_accounts_primarykey;",
      "CREATE TRIGGER update_ensure_main_accounts_primarykey\n  BEFORE UPDATE ON \"main\".\"accounts\"\nBEGIN\n  SELECT\n    CASE\n      WHEN old.\"provider\" != new.\"provider\" THEN\n      \t\tRAISE (ABORT, 'cannot change the value of column provider as it belongs to the primary key')\n      WHEN old.\"provider_account_id\" != new.\"provider_account_id\" THEN\n      \t\tRAISE (ABORT, 'cannot change the value of column provider_account_id as it belongs to the primary key')\n    END;\nEND;",
      "DROP TRIGGER IF EXISTS insert_main_accounts_into_oplog;",
      "CREATE TRIGGER insert_main_accounts_into_oplog\n   AFTER INSERT ON \"main\".\"accounts\"\n   WHEN 1 = (SELECT flag from _electric_trigger_settings WHERE namespace = 'main' AND tablename = 'accounts')\nBEGIN\n  INSERT INTO _electric_oplog (namespace, tablename, optype, primaryKey, newRow, oldRow, timestamp)\n  VALUES ('main', 'accounts', 'INSERT', json_patch('{}', json_object('provider', new.\"provider\", 'provider_account_id', new.\"provider_account_id\")), json_object('access_token', new.\"access_token\", 'expires_at', new.\"expires_at\", 'id_token', new.\"id_token\", 'provider', new.\"provider\", 'provider_account_id', new.\"provider_account_id\", 'refresh_token', new.\"refresh_token\", 'scope', new.\"scope\", 'session_state', new.\"session_state\", 'token_type', new.\"token_type\", 'type', new.\"type\", 'userId', new.\"userId\"), NULL, NULL);\nEND;",
      "DROP TRIGGER IF EXISTS update_main_accounts_into_oplog;",
      "CREATE TRIGGER update_main_accounts_into_oplog\n   AFTER UPDATE ON \"main\".\"accounts\"\n   WHEN 1 = (SELECT flag from _electric_trigger_settings WHERE namespace = 'main' AND tablename = 'accounts')\nBEGIN\n  INSERT INTO _electric_oplog (namespace, tablename, optype, primaryKey, newRow, oldRow, timestamp)\n  VALUES ('main', 'accounts', 'UPDATE', json_patch('{}', json_object('provider', new.\"provider\", 'provider_account_id', new.\"provider_account_id\")), json_object('access_token', new.\"access_token\", 'expires_at', new.\"expires_at\", 'id_token', new.\"id_token\", 'provider', new.\"provider\", 'provider_account_id', new.\"provider_account_id\", 'refresh_token', new.\"refresh_token\", 'scope', new.\"scope\", 'session_state', new.\"session_state\", 'token_type', new.\"token_type\", 'type', new.\"type\", 'userId', new.\"userId\"), json_object('access_token', old.\"access_token\", 'expires_at', old.\"expires_at\", 'id_token', old.\"id_token\", 'provider', old.\"provider\", 'provider_account_id', old.\"provider_account_id\", 'refresh_token', old.\"refresh_token\", 'scope', old.\"scope\", 'session_state', old.\"session_state\", 'token_type', old.\"token_type\", 'type', old.\"type\", 'userId', old.\"userId\"), NULL);\nEND;",
      "DROP TRIGGER IF EXISTS delete_main_accounts_into_oplog;",
      "CREATE TRIGGER delete_main_accounts_into_oplog\n   AFTER DELETE ON \"main\".\"accounts\"\n   WHEN 1 = (SELECT flag from _electric_trigger_settings WHERE namespace = 'main' AND tablename = 'accounts')\nBEGIN\n  INSERT INTO _electric_oplog (namespace, tablename, optype, primaryKey, newRow, oldRow, timestamp)\n  VALUES ('main', 'accounts', 'DELETE', json_patch('{}', json_object('provider', old.\"provider\", 'provider_account_id', old.\"provider_account_id\")), NULL, json_object('access_token', old.\"access_token\", 'expires_at', old.\"expires_at\", 'id_token', old.\"id_token\", 'provider', old.\"provider\", 'provider_account_id', old.\"provider_account_id\", 'refresh_token', old.\"refresh_token\", 'scope', old.\"scope\", 'session_state', old.\"session_state\", 'token_type', old.\"token_type\", 'type', old.\"type\", 'userId', old.\"userId\"), NULL);\nEND;",
      "DROP TRIGGER IF EXISTS compensation_insert_main_accounts_userId_into_oplog;",
      "CREATE TRIGGER compensation_insert_main_accounts_userId_into_oplog\n  AFTER INSERT ON \"main\".\"accounts\"\n  WHEN 1 = (SELECT flag from _electric_trigger_settings WHERE namespace = 'main' AND tablename = 'accounts') AND\n       1 = (SELECT value from _electric_meta WHERE key = 'compensations')\nBEGIN\n  INSERT INTO _electric_oplog (namespace, tablename, optype, primaryKey, newRow, oldRow, timestamp)\n  SELECT 'main', 'users', 'COMPENSATION', json_patch('{}', json_object('id', \"id\")), json_object('id', \"id\"), NULL, NULL\n  FROM \"main\".\"users\" WHERE \"id\" = new.\"userId\";\nEND;",
      "DROP TRIGGER IF EXISTS compensation_update_main_accounts_userId_into_oplog;",
      "CREATE TRIGGER compensation_update_main_accounts_userId_into_oplog\n  AFTER UPDATE ON \"main\".\"accounts\"\n  WHEN 1 = (SELECT flag from _electric_trigger_settings WHERE namespace = 'main' AND tablename = 'accounts') AND\n       1 = (SELECT value from _electric_meta WHERE key = 'compensations')\nBEGIN\n  INSERT INTO _electric_oplog (namespace, tablename, optype, primaryKey, newRow, oldRow, timestamp)\n  SELECT 'main', 'users', 'COMPENSATION', json_patch('{}', json_object('id', \"id\")), json_object('id', \"id\"), NULL, NULL\n  FROM \"main\".\"users\" WHERE \"id\" = new.\"userId\";\nEND;",
